#!/usr/bin/env bash
# Downloads all real (original, licensed) 3D assets used by HyperCity 3D.
# Nothing here is generated by hand - every model comes from a credited source.
set -u
cd "$(dirname "$0")/.."

PUB=public/assets
CITY=$PUB/city
VEH=$PUB/vehicles
AIR=$PUB/air
CHR=$PUB/characters
NAT=$PUB/nature
MISC=$PUB/misc
DATA=public/data
mkdir -p "$CITY" "$VEH" "$AIR" "$CHR" "$NAT" "$MISC" "$DATA"

dl () { # dl <url> <out>
  local url="$1" out="$2"
  if [ -s "$out" ]; then echo "skip  $out"; return 0; fi
  curl -fL --retry 3 --retry-delay 2 --max-time 600 -o "$out.part" "$url" \
    && mv "$out.part" "$out" && echo "ok    $out ($(du -h "$out" | cut -f1))" \
    || echo "FAIL  $out  <- $url"
}

echo "### OpenStreetMap-derived city (linranff/GTA_SZ, ODbL-1.0)"
B=https://media.githubusercontent.com/media/linranff/GTA_SZ/main/public/city
dl "$B/buildings.glb"          "$CITY/buildings.glb"
dl "$B/facades.glb"            "$CITY/facades.glb"
dl "$B/roads.glb"              "$CITY/roads.glb"
dl "$B/terrain.glb"            "$CITY/terrain.glb"
dl "$B/coastal-bridges.glb"    "$CITY/coastal-bridges.glb"
dl "$B/coastal-shoreline.glb"  "$CITY/coastal-shoreline.glb"
dl "$B/tree.glb"               "$NAT/tree.glb"
dl "$B/palm.glb"               "$NAT/palm.glb"
dl "$B/park-floodlight.glb"    "$MISC/park-floodlight.glb"
dl "$B/life-hub.glb"           "$MISC/life-hub.glb"

echo "### Vehicles (Khronos CarConcept via GTA_SZ, CC BY 4.0)"
dl "$B/car.glb"                "$VEH/car.glb"
dl "$B/traffic-car.glb"        "$VEH/traffic-car.glb"
dl "$B/floatplane.glb"         "$AIR/floatplane.glb"
dl "$B/pedestrian.glb"         "$CHR/pedestrian.glb"

echo "### City layout data"
dl "https://raw.githubusercontent.com/linranff/GTA_SZ/main/public/city/city.json" "$DATA/city.json"

echo "### Aircraft + characters (ir-engine/ir-engine-assets-basic, Apache-2.0)"
I=https://media.githubusercontent.com/media/ir-engine/ir-engine-assets-basic/main/assets
dl "$I/aircraft_and_war/Attackhelicopter.glb" "$AIR/helicopter.glb"
dl "$I/aircraft_and_war/Aerobaticairplane.glb" "$AIR/airplane.glb"
dl "$I/aircraft_and_war/Landingjet.glb"        "$AIR/jet.glb"
dl "$I/aircraft_and_war/Flyingdrone.glb"       "$AIR/drone.glb"

echo "### Characters with animation (three.js examples, MIT/CC)"
T=https://raw.githubusercontent.com/mrdoob/three.js/dev/examples/models/gltf
dl "$T/Soldier.glb" "$CHR/soldier.glb"
dl "$T/Xbot.glb"    "$CHR/xbot.glb"
dl "$T/RobotExpressive/RobotExpressive.glb" "$CHR/robot.glb"
dl "$T/LittlestTokyo.glb" "$MISC/littlest-tokyo.glb"

echo "### Animals / nature (three.js examples)"
dl "$T/Horse.glb"    "$NAT/horse.glb"
dl "$T/Flamingo.glb" "$NAT/flamingo.glb"
dl "$T/Parrot.glb"   "$NAT/parrot.glb"
dl "$T/Stork.glb"    "$NAT/stork.glb"

echo "### Licences / attribution"
L=https://raw.githubusercontent.com/linranff/GTA_SZ/main/public/licenses
dl "$L/carconcept-CC-BY-4.0.md" "$MISC/LICENSE-carconcept-CC-BY-4.0.md"
dl "$L/open-city-assets.md"     "$MISC/LICENSE-open-city-assets.md"

echo "### DONE"
